class Solution:
    def findDuplicateSubtrees(self, root: Optional[TreeNode]) -> List[Optional[TreeNode]]:
        counts = {}
        duplicates = []

        def serialize(node: Optional[TreeNode]) -> str:
            if not node:
                return "#"
            serial = f"{node.val},{serialize(node.left)},{serialize(node.right)}"
            counts[serial] = counts.get(serial, 0) + 1
            if counts[serial] == 2:
                duplicates.append(node)
            return serial

        serialize(root)
        return duplicates

class Solution {
    string serialize(TreeNode* node, unordered_map<string, int>& counts, vector<TreeNode*>& duplicates) {
        if (!node) return "#";
        string s = to_string(node->val) + "," + serialize(node->left, counts, duplicates) + "," + serialize(node->right, counts, duplicates);
        counts[s]++;
        if (counts[s] == 2) {
            duplicates.push_back(node);
        }
        return s;
    }
public:
    vector<TreeNode*> findDuplicateSubtrees(TreeNode* root) {
        unordered_map<string, int> counts;
        vector<TreeNode*> duplicates;
        serialize(root, counts, duplicates);
        return duplicates;
    }
};

class Solution {
    public List<TreeNode> findDuplicateSubtrees(TreeNode root) {
        Map<String, Integer> counts = new HashMap<>();
        List<TreeNode> duplicates = new ArrayList<>();
        serialize(root, counts, duplicates);
        return duplicates;
    }

    private String serialize(TreeNode node, Map<String, Integer> counts, List<TreeNode> duplicates) {
        if (node == null) return "#";
        String s = node.val + "," + serialize(node.left, counts, duplicates) + "," + serialize(node.right, counts, duplicates);
        counts.put(s, counts.getOrDefault(s, 0) + 1);
        if (counts.get(s) == 2) {
            duplicates.add(node);
        }
        return s;
    }
}

var findDuplicateSubtrees = function(root) {
    const counts = new Map();
    const duplicates = [];

    function serialize(node) {
        if (!node) return '#';
        const s = node.val + ',' + serialize(node.left) + ',' + serialize(node.right);
        counts.set(s, (counts.get(s) || 0) + 1);
        if (counts.get(s) === 2) {
            duplicates.push(node);
        }
        return s;
    }

    serialize(root);
    return duplicates;
};
